{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Are Machine Learning methods effective in detecting undiagnosed atrial fibrillation in primary care settings using electronic health records? A systematic review",
      "reason": "The title explicitly includes the phrase \"A systematic review\"."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Are Machine Learning methods effective in detecting undiagnosed atrial fibrillation in primary care settings using electronic health records? A systematic review",
      "reason": "The title clearly states the objective (effectiveness of Machine Learning methods in detecting undiagnosed atrial fibrillation), the population (primary care settings), and the intervention/exposure (electronic health records)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The title does not contain supplementary information such as analysis method, study designs, or update status, and this element is conditional."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "While evidence on this approach is expanding, it remains unclear how these EHR-based models perform compared to standard care. Many studies lack direct comparisons, and questions remain about the generalizability of ML models in primary care due to variability in validation methods and dataset limitations.",
      "reason": "The manuscript describes the current state of knowledge regarding ML models for AF detection in primary care and highlights uncertainties, specifically regarding their performance compared to standard care and issues with generalizability."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Given the high risks associated with untreated AF and the limitations of current screening methods, a more reliable, efficient, and integrated approach is urgently needed in primary care. ... A systematic synthesis of current evidence is therefore necessary to assess the benefits and limitations of ML-based tools for AF screening using EHR.",
      "reason": "The manuscript explicitly explains the importance and need for the review, citing the risks of untreated AF, the limitations of current screening, and the necessity of synthesizing evidence to assess ML-based tools."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Himmelreich et al.'s systematic review also identified the Cohorts for Heart and Aging Research in Genomic Epidemiology for Atrial Fibrillation (CHARGE-AF) model as the most successful for predicting incident AF over a five-year window. Despite widespread validation and readily available clinical metrics, CHARGE-AF has limitations such as primarily studied in three American cohorts which is limiting its applicability to non-white populations.",
      "reason": "The manuscript identifies a previous systematic review (Himmelreich et al.) and explains the need for the current review by contrasting the limitations of existing models (like CHARGE-AF) with the potential of the EHR-based ML approach being reviewed."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This review evaluates diagnostic/predictive models (ML models for AF detection) rather than the effects of a therapeutic intervention, so a mechanism of action is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review focuses on the diagnostic performance of ML models rather than evaluating a complex intervention or delivery context requiring a logic model."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "We conducted a systematic review to evaluate the effectiveness, quality, and applicability of EHR-based ML models for detecting AF in primary care.",
      "reason": "The review explicitly states its objective in the abstract."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The PICOS (population, intervention, comparator, outcome) framework [16] was used to develop the inclusion and exclusion criteria for suitable studies.",
      "reason": "The review explicitly states the use of the PICOS framework to define the inclusion/exclusion criteria, which serves as the question-formulation framework for this review of intervention effects."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Population : Studies involving adult populations (aged >18 years) were included. Intervention : Oly studies that developed and/or applied ML methods using data from EHRs or primary care databases to detect new cases of AF within a primary care context were included. ... Comparison : Standard care practices or validated clinical risk scores for AF. Outcome: The primary outcome of interest was the incidence of new AF diagnoses following the application of ML methods. ... Settings: Eligible studies were conducted within primary care or outpatient settings",
      "reason": "The manuscript explicitly defines the inclusion and exclusion criteria using the PICOS framework, covering population, intervention, comparison, outcome, and settings."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "We included peer-reviewed publications in English using the PICOS framework.",
      "reason": "The manuscript specifies the language (English) and publication status (peer-reviewed publications) as part of the eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not report excluding studies based on the distinction between outcomes not measured versus outcomes not reported; it focuses on prediction models and their performance metrics."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "This involved using textual descriptions of each study, grouping and clustering by relevant characteristics, and tabulating key effectiveness measures, with a particular focus on model performance metrics such as sensitivity, specificity, positive predictive value, accuracy, ROC-AUC, PRC-AUC, and F1 score. We also explored sources of variation across studies, including differences in study design, methodology, populations, interventions, control groups, and outcomes.",
      "reason": "The manuscript describes the synthesis approach, which involved grouping and clustering studies by relevant characteristics (design, methodology, populations, interventions, control groups, outcomes) and tabulating key performance metrics."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There are no notable restrictions on study eligibility that require a specific rationale beyond the standard PICOS criteria provided."
    }
  ],
  "confidence": 100
}

